def convert_text(content_text):
    def is_letter(c):
        return ('a' <= c <= 'z') or ('A' <= c <= 'Z')

    def convert_word(word):
        # Rule 1: starts with a non-letter (or empty) -> unchanged
        if not word or not is_letter(word[0]):
            return word
        # Rule 2: two or more non-empty parts of English letters joined by hyphens
        parts = word.split('-')
        if len(parts) >= 2 and all(p and all(is_letter(c) for c in p) for p in parts):
            return '-'.join(p[0].upper() + p[1:].lower() for p in parts)
        # Rule 3: first letter upper, other letters lower, special characters unchanged
        return word[0].upper() + word[1:].lower()

    return ' '.join(convert_word(w) for w in content_text.split(' '))
